import{_ as o,C as n,c as r,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const q=JSON.parse('{"title":"Equipment categories","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/setup/equipment-categories.md","filePath":"master/supply-chain/maintenance/setup/equipment-categories.md","lastUpdated":1793074831000}'),l={name:"master/supply-chain/maintenance/setup/equipment-categories.md"};function c(g,e,p,h,u,m){const a=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="equipment-categories" tabindex="-1">Equipment categories <a class="header-anchor" href="#equipment-categories" aria-label="Permalink to &quot;Equipment categories&quot;">​</a></h1><p>An equipment category groups similar equipment, for example <strong>Packaging Machines</strong>, <strong>IT Equipment</strong> or <strong>Vehicles</strong>. It also names one person who is responsible for that kind of equipment. This saves typing, because the person flows into new requests.</p><blockquote><p><strong>In simple words:</strong> A category is a folder for similar machines, with a default person in charge.</p></blockquote><p>Open <code>Maintenance → Configurations → Categories</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>The <strong>Responsible</strong> person is a user. Create users first in <a href="./../../../general-settings/users/manage-users.html">Manage users</a>. Make the category before you <a href="./../equipment/add-equipment.html">add equipment</a>, because equipment picks a category.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows <strong>Name</strong>, <strong>Responsible</strong> and <strong>Company</strong>. Use <strong>Group by</strong> to group rows by <strong>Responsible</strong>. Use the search box to find a category by name. Each row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong> actions.</p>',7)),s(a,{src:"/images1/maintenance/set_categories_list.png",alt:"Equipment Categories list showing Packaging Machines with Responsible Linda Ndlovu beside other categories"}),e[1]||(e[1]=t('<h2 id="create-a-category" tabindex="-1">Create a category <a class="header-anchor" href="#create-a-category" aria-label="Permalink to &quot;Create a category&quot;">​</a></h2><p>This example makes <strong>Packaging Machines</strong>, with Linda Ndlovu in charge.</p><ol><li>Open <code>Maintenance → Configurations → Categories</code>.</li><li>Click <strong>New Category</strong>. A full page opens.</li><li>Fill in the <strong>General Information</strong> section.</li></ol><ul><li><strong><em>Name:</em></strong> Required. Type <code>Packaging Machines</code>.</li><li><strong><em>Responsible:</em></strong> The person in charge of this kind of equipment. It starts as you. Choose <strong>Linda Ndlovu</strong>.</li><li><strong><em>Company:</em></strong> Fills with your company.</li><li><strong><em>Note:</em></strong> Optional text for your team, such as where these machines are kept.</li></ul>',4)),s(a,{src:"/images1/maintenance/set_category_form.png",alt:"Create Equipment Category form filled with Packaging Machines and Responsible Linda Ndlovu"}),e[2]||(e[2]=t('<ol start="4"><li>Click <strong>Create</strong>. The notification <strong>Category created</strong> appears with the text &quot;The category has been created successfully.&quot; The category opens on its view page.</li></ol><p>You can also click <strong>Create &amp; create another</strong> or <strong>Cancel</strong>.</p><h2 id="why-responsible-matters" tabindex="-1">Why Responsible matters <a class="header-anchor" href="#why-responsible-matters" aria-label="Permalink to &quot;Why Responsible matters&quot;">​</a></h2><p>The <strong>Responsible</strong> person becomes the default technician. When you pick equipment of this category on a request, Aureus fills <strong>Responsible</strong> with the equipment technician. On the equipment form, choosing the category fills <strong>Technician</strong> with this person. If the equipment has none, it uses the category&#39;s person. If that is empty too, it uses you.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Pick the person who usually leads the repairs. You can still change the responsible person on any single request.</p></div><h2 id="edit-or-delete-a-category" tabindex="-1">Edit or delete a category <a class="header-anchor" href="#edit-or-delete-a-category" aria-label="Permalink to &quot;Edit or delete a category&quot;">​</a></h2><p>Click <strong>View</strong> to read a category. Click <strong>Edit</strong> to change fields, then <strong>Save changes</strong>. Click <strong>Delete</strong> to remove it.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A category used by equipment is hard to remove. Move the equipment to another category first.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./maintenance-teams.html">Maintenance teams</a></li><li><a href="./../equipment/add-equipment.html">Add equipment</a></li><li><a href="./../requests/create-request.html">Create a maintenance request</a></li></ul>',10))])}const f=o(l,[["render",c]]);export{q as __pageData,f as default};
